// Collection service (git-backed): open, Save, Folders, Drafts, Conflicts, offline queue.
// The UI only calls Tauri commands; types come from Rust (src/bindings, generated by ts-rs).
import { invoke } from "@tauri-apps/api/core";
import type { Change } from "@/bindings/Change";
import type { FolderOp } from "@/bindings/FolderOp";
import type { TreeChange } from "@/bindings/TreeChange";
import type { BatchResult } from "@/bindings/BatchResult";
import type { Draft } from "@/bindings/Draft";
import type { ImportReport } from "@/bindings/ImportReport";
import type { ConflictInfo } from "@/bindings/ConflictInfo";
import type { SaveResult } from "@/bindings/SaveResult";
import type { AttemptResult } from "@/bindings/AttemptResult";
import type { DrainReport } from "@/bindings/DrainReport";
import type { OfflineStatus } from "@/bindings/OfflineStatus";
import type { SyncReport } from "@/bindings/SyncReport";
import type { CollectionData } from "@/bindings/CollectionData";
import type { Defaults } from "@/bindings/Defaults";
import type { SharedSave } from "@/bindings/SharedSave";
import type { RequestItem } from "@/bindings/RequestItem";

export const openCollection = (path: string) => invoke<CollectionData>("open_collection", { path });

// Save = fetch, merge by Field, commit, push.
// Inherited headers/auth of the Collection (`folderId` null) or a Folder are shared the same way.
export const saveDefaults = (path: string, folderId: string | null, base: Defaults, ours: Defaults, overwrite = false) =>
  invoke<SharedSave>("save_defaults", { path, folderId, base, ours, overwrite });
// Background fetch of other Members' Saves (not a user action; the user only ever Saves).
export const syncCollection = (path: string) => invoke<SyncReport>("sync_collection", { path });
// `folderId`: the Folder a Request is created in / moved into, followed by id if renamed remotely.
export const saveChange = (path: string, change: Change, folderId: string | null = null) =>
  invoke<SaveResult>("save_change", { path, change, folderId });
export const folderOp = (path: string, op: FolderOp) => invoke<SaveResult>("folder_op", { path, op });
/** Several tree changes (multi-select drag / delete) as one commit and one push; conflicting ones are left out. */
export const saveBatch = (path: string, changes: TreeChange[]) => invoke<BatchResult>("save_batch", { path, changes });
export const importPostman = (path: string, json: string) => invoke<ImportReport>("import_postman", { path, json });
/** Write the Collection as a Postman v2.1 file at `file`; returns what Postman cannot hold. */
export const exportCollection = (path: string, file: string) => invoke<string[]>("export_collection", { path, file });
export const listDrafts = (path: string) => invoke<Draft[]>("list_drafts", { path });
export const putDraft = (path: string, base: RequestItem | null, draft: RequestItem) =>
  invoke<void>("put_draft", { path, base, draft });
export const discardDraft = (path: string, requestId: string) => invoke<void>("discard_draft", { path, requestId });

// Conflict resolution (after Save reports a Conflict).
export const conflictInfo = (path: string, change: Change) => invoke<ConflictInfo>("conflict_info", { path, change });
export const overwriteChange = (path: string, change: Change) => invoke<SaveResult>("overwrite_change", { path, change });
export const cancelChange = (path: string, change: Change) => invoke<Draft | null>("cancel_change", { path, change });

// Offline queue, Needs Attention and Viewer state.
export const saveOrQueue = (path: string, change: Change, folderId: string | null = null) =>
  invoke<AttemptResult>("save_or_queue", { path, change, folderId });
export const drainQueue = (path: string) => invoke<DrainReport>("drain_queue", { path });
export const offlineStatus = (path: string) => invoke<OfflineStatus>("offline_status", { path });
